slug: outbox-relay-deletes-before-publish
stack: dotnet
topic: distributed
level: senior
type: find-bug
grading: auto
tags: [outbox, at-least-once, messaging, reliability]
code:
  language: csharp
  harness: statements
  source: |
    var outbox = new List<string> { "OrderCreated:42" };
    var broker = new FakeBroker();

    for (int pass = 1; pass <= 2; pass++)
    {
        try
        {
            while (outbox.Count > 0)
            {
                string message = outbox[0];
                outbox.RemoveAt(0);
                broker.Publish(message);
            }
        }
        catch (InvalidOperationException)
        {
            Console.WriteLine($"Pass {pass}: broker unavailable");
        }
    }

    Console.WriteLine($"Published: {broker.Published.Count}");

    class FakeBroker
    {
        private int _calls;
        public List<string> Published { get; } = new();

        public void Publish(string message)
        {
            _calls++;
            if (_calls == 1)
            {
                // The first publish fails, as during a short broker outage.
                throw new InvalidOperationException("Broker unavailable");
            }
            Published.Add(message);
        }
    }
bugLineSets: [[11], [11, 12]]
fixedSource: |
  var outbox = new List<string> { "OrderCreated:42" };
  var broker = new FakeBroker();

  for (int pass = 1; pass <= 2; pass++)
  {
      try
      {
          while (outbox.Count > 0)
          {
              string message = outbox[0];
              broker.Publish(message);
              // Remove the row only after the broker accepted the message.
              outbox.RemoveAt(0);
          }
      }
      catch (InvalidOperationException)
      {
          Console.WriteLine($"Pass {pass}: broker unavailable");
      }
  }

  Console.WriteLine($"Published: {broker.Published.Count}");

  class FakeBroker
  {
      private int _calls;
      public List<string> Published { get; } = new();

      public void Publish(string message)
      {
          _calls++;
          if (_calls == 1)
          {
              // The first publish fails, as during a short broker outage.
              throw new InvalidOperationException("Broker unavailable");
          }
          Published.Add(message);
      }
  }
fixedExpect: { kind: output, value: "Pass 1: broker unavailable\nPublished: 1" }
